class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        n = len(points)
        ans = float('-inf')
        for j in range(1, n):
            for i in range(j):
                dx = points[j][0] - points[i][0]
                if dx > k:
                    break
                ans = max(ans, points[i][1] + points[j][1] + dx)
        return ans

