import heapq

class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        ans = float('-inf')
        heap = []
        for x, y in points:
            while heap and x - heap[0][1] > k:
                heapq.heappop(heap)
            if heap:
                ans = max(ans, y + x - heap[0][0])
            heapq.heappush(heap, (x - y, x))
        return ans

