    int findMaxValueOfEquation(vector<vector<int>>& points, int k) {
        priority_queue<pair<int,int>> pq;
        long long ans = LLONG_MIN;
        for (auto& p : points) {
            while (!pq.empty() && p[0] - pq.top().second > k) pq.pop();
            if (!pq.empty())
                ans = max(ans, (long long)p[1] + p[0] + pq.top().first);
            pq.push({p[1] - p[0], p[0]});
        }
        return (int)ans;
    }
};

