var findMaxValueOfEquation = function(points, k) {
    // simple binary-heap based priority queue
    const heap = [];
    const push = (v) => { heap.push(v); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1;
            if (heap[p][0] >= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const t = heap[0], l = heap.pop();
        if (heap.length) { heap[0] = l; let i = 0;
            for (;;) { let c = 2 * i + 1; if (c >= heap.length) break;
                if (c + 1 < heap.length && heap[c + 1][0] > heap[c][0]) c++;
                if (heap[i][0] >= heap[c][0]) break;
                [heap[i], heap[c]] = [heap[c], heap[i]]; i = c; } }
        return t; };
    let ans = -Infinity;
    for (const [x, y] of points) {
        while (heap.length && x - heap[0][1] > k) pop();
        if (heap.length) ans = Math.max(ans, y + x + heap[0][0]);
        push([y - x, x]);
    }
    return ans;
};

