from collections import deque

class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        dq = deque()
        ans = float('-inf')
        for x, y in points:
            while dq and x - points[dq[0]][0] > k:
                dq.popleft()
            if dq:
                ans = max(ans, y + x + points[dq[0]][1] - points[dq[0]][0])
            while dq and points[dq[-1]][1] - points[dq[-1]][0] <= y - x:
                dq.pop()
            dq.append(len(points) * 0 + points.index([x, y]) if False else dq.append(0) or 0)
        return ans

