        deque<int> dq;
        long long ans = LLONG_MIN;
        for (int j = 0; j < (int)points.size(); j++) {
            while (!dq.empty() && (long long)points[j][0] - points[dq.front()][0] > k)
                dq.pop_front();
            if (!dq.empty())
                ans = max(ans, (long long)points[j][1] + points[j][0]
                        + points[dq.front()][1] - points[dq.front()][0]);
            while (!dq.empty() && points[dq.back()][1] - points[dq.back()][0] <= points[j][1] - points[j][0])
                dq.pop_back();
            dq.push_back(j);
        }
        return (int)ans;
    }
};

