class Solution {
    public int findMaxValueOfEquation(int[][] points, int k) {
        Deque<Integer> dq = new ArrayDeque<>();
        long ans = Long.MIN_VALUE;
        for (int j = 0; j < points.length; j++) {
            while (!dq.isEmpty() && (long) points[j][0] - points[dq.peekFirst()][0] > k)
                dq.pollFirst();
            if (!dq.isEmpty())
                ans = Math.max(ans, (long) points[j][1] + points[j][0]
                        + points[dq.peekFirst()][1] - points[dq.peekFirst()][0]);
            while (!dq.isEmpty()
                    && points[dq.peekLast()][1] - points[dq.peekLast()][0] <= points[j][1] - points[j][0])
                dq.pollLast();
            dq.addLast(j);
        }
        return (int) ans;
    }
}

