var findMaxValueOfEquation = function(points, k) {
    const dq = [];
    let head = 0;
    let ans = -Infinity;
    for (let j = 0; j < points.length; j++) {
        while (head < dq.length && points[j][0] - points[dq[head]][0] > k) head++;
        if (head < dq.length) {
            const f = dq[head];
            ans = Math.max(ans, points[j][1] + points[j][0] + points[f][1] - points[f][0]);
        }
        while (dq.length > head &&
               points[dq[dq.length - 1]][1] - points[dq[dq.length - 1]][0] <= points[j][1] - points[j][0])
            dq.pop();
        dq.push(j);
    }
    return ans;
};
